impl Solution {
    pub fn count_subarrays(nums: Vec<i32>) -> i32 {
        let mut count = 0;
        for i in 1..nums.len() - 1 {
            if 2 * (nums[i - 1] + nums[i + 1]) == nums[i] {
                count += 1;
            }
        }
        count
    }
}

